import React from 'react';

export const Button = ({ children, variant = 'primary', size = 'medium', asChild = false, ...props }) => {
  const base = 'inline-flex items-center justify-center rounded-md font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50';
  const sizeMap = {
    small: 'h-9 px-3 text-sm',
    medium: 'h-10 px-4 py-2',
    large: 'h-11 px-6 text-lg',
  };
  const variantMap = {
    primary: 'bg-primary-600 text-primary-foreground hover:bg-primary-700',
    secondary: 'bg-secondary-600 text-secondary-foreground hover:bg-secondary-700',
    destructive: 'bg-destructive text-destructive-foreground hover:bg-destructive/80',
    outline: 'border border-input hover:bg-accent hover:text-accent-foreground',
    ghost: 'hover:bg-accent hover:text-accent-foreground',
    link: 'underline-offset-4 hover:underline text-primary-600',
  };

  const AsChild = asChild ? 'span' : 'button';

  return (
    <AsChild
      className={`${base} ${sizeMap[size]} ${variantMap[variant]}`}
      {...props}
    >
      {children}
    </AsChild>
  );
};

// Export as default for ease of use
export default Button;

